import request from '@/utils/request'

export function getActiveList() {
  return request({
    url: '/activity/activlist',
    method: 'get'
  })
}
export function getActinfo(query) {
  return request({
    url: '/activity/getActinfo',
    method: 'get',
    params: query
  })
}

export function throughtling(params) { // 领取
  return request({
    url: '/activity/throughtling',
    method: 'get',
    params
  })
}

export function bibisongling(params) { // 充值笔笔送领取
  return request({
    url: '/activity/bibisongling',
    method: 'get',
    params
  })
}
